p='src/agent.ts'
s=open(p).read()
old='''        const avail = this.skillManager.listSkills().map((s) => s.name).join(", ");
        return {
          success: false,
          output: "",
          error: `Error: Skill '${skillName}' not found. Available skills: ${avail || "none"}`,
        };'''
new='''        // No skill has that name: treat the text as a search. Matching advertises descriptions and activates nothing.
        const matches = this.skillManager.findSkills(String(skillName ?? ""), MAX_SKILL_MATCHES);
        if (!matches.length) {
          return { success: true, output: `No installed skill matches '${skillName}'. Nothing was activated; try other words describing the task.` };
        }
        return {
          success: true,
          output: `No skill is named '${skillName}'. Nothing was activated. Installed skills that match those words; call activate_skill again with an exact name to load one:\\n${matches.map((s) => `- **${s.name}**: ${s.description}`).join("\\n")}`,
        };'''
assert old in s
s=s.replace(old,new)
open(p,'w').write(s)
p='src/core/capability_definitions/skill.ts'
s=open(p).read()
s=s.replace("The name of the skill to activate (e.g. 'graphify').","The skill to activate (e.g. 'graphify'). If no skill has exactly this name, it is used as a search and the best matching skills are listed.")
open(p,'w').write(s)
EOF
/usr/bin/grep -rn "The name of the skill to activate" .. --include=*.rs --include=*.json --include=*.ts -l 2>/dev/null | grep -v node_modules | head

